-- LangConfig additive agent seed — generated by export_agents_merge.py
-- 66 agent(s) from the live database.
--
-- Safe to run on a database that already has agents: an id is reused when
-- it is free, the insert is skipped when the name already exists, and the
-- sequence is moved past the highest id at the end. Names are matched, not
-- ids, so a teammate's own agents are never overwritten.
--
-- Machine paths are stored as WORKSPACE_BASE/... and re-resolved per install
-- by seed_all step 8.5 (backfill_agent_identity.py).
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f deep_agents_merge.sql

BEGIN;

