ath you were given points there.\n"}', '{"model": "deepseek-flash", "tools": ["ls", "read_file", "edit_file", "glob", "grep"], "skills": ["data-analysis", "ticket-classifier", "web-search"], "backend": {"type": "state", "config": {}, "mappings": null}, "cli_tools": [], "subagents": [{"name": "data-analysis", "description": "Content-independent data analysis mechanics. Provides chart types, tool usage patterns, and edge case handling for CSV and SQL data. Pair with a dataset-specific .skill.md for column semantics and business context.", "system_prompt": "You are a data-analysis specialist. Read the SKILL.md and follow its instructions exactly. Return only the result."}, {"name": "web-search", "description": "Search the web for the latest news, current events, and recent information. Use when the user asks about today''s news, current events, breaking news, recent updates, latest developments, or any extern", "system_prompt": "You are a web-search specialist. Read the SKILL.md and follow its instructions exactly. Return only the result."}, {"name": "ticket-classifier", "description": "Classifies customer support tickets by priority, category, and sentiment", "system_prompt": "You are a ticket-classifier specialist. Read the SKILL.md and follow its instructions exactly. Return only the result."}], "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "long_term_memory": false, "enable_auto_eviction": true, "enable_summarization": true}, "max_tokens": null, "middleware": [], "modalities": null, "temperature": 0.7, "custom_tools": [], "native_tools": ["think_tool", "reasoning_chain", "write_todos", "read_todos", "web_search", "web_fetch", "rename_file", "move_file", "mkdir", "bash", "skill", "memory_store", "memory_recall", "pg_list_tables", "pg_describe_table", "pg_query", "pg_list_agents", "pg_get_agent", "pg_list_projects", "sqlite_execute", "sqlite_load_csv", "python_execute", "s